13	// helpTree builds a fixed tree used by several help tests:
14	//
15	//	tool (handler, desc "root tool")
16	//	├── serve (aliases srv, s; handler; desc "serve requests")
17	//	│   └── stop (no aliases, no handler, desc "stop serving")
18	//	└── config (no handler, no desc)
19	func helpTree(t *testing.T) *Node {
20		t.Helper()
21		root := New("tool", "root tool", nil, noop)
22		serve := New("serve", "serve requests", []string{"srv", "s"}, noop)
23		stop := New("stop", "stop serving", nil, nil)
24		if err := serve.Add(stop); err != nil {
25			t.Fatalf("Add(stop): %v", err)
26		}
27		if err := root.Add(serve); err != nil {
28			t.Fatalf("Add(serve): %v", err)
29		}
30		if err := root.Add(New("config", "", nil, nil)); err != nil {
31			t.Fatalf("Add(config): %v", err)
32		}
33		return root
34	}
