36	func helpString(t *testing.T, n *Node, path []string, p *Parser) string {
37		t.Helper()
38		var buf bytes.Buffer
39		if err := n.WriteHelp(path, p, &buf); err != nil {
40			t.Fatalf("WriteHelp(%v) error: %v", path, err)
41		}
42		return buf.String()
43	}
