55		root := helpTree(t)
56		got := helpString(t, root, []string{}, nil)
57		if !strings.HasPrefix(got, "Usage: tool ") {
58			t.Errorf("empty path should select the current node, got %q", got)
59		}
60	}
61	
62	func TestWriteHelpUsageCommandMarkers(t *testing.T) {
63		root := helpTree(t)
64	
65		// Node with children and a handler: [command].
66		got := helpString(t, root, nil, nil)
67		if !strings.HasPrefix(got, "Usage: tool [command]\n") {
68			t.Errorf("root usage = %q, want [command] marker", got)
69		}
70	
71		// Node with children but no handler: <command>.
72		config := New("cfg", "", nil, nil)
73		if err := config.Add(New("sub", "", nil, noop)); err != nil {
74			t.Fatal(err)
