89		root := helpTree(t)
90		got := helpString(t, root, []string{"s"}, nil)
91		if !strings.HasPrefix(got, "Usage: tool serve ") {
92			t.Errorf("alias path should render canonical names, got %q", got)
93		}
94		got = helpString(t, root, []string{"srv", "stop"}, nil)
95		if !strings.HasPrefix(got, "Usage: tool serve stop\n") {
96			t.Errorf("nested alias path should render canonical names, got %q", got)
97		}
98	}
99	
100	func TestWriteHelpCaseSensitiveMiss(t *testing.T) {
101		root := helpTree(t)
102		var buf bytes.Buffer
103		err := root.WriteHelp([]string{"Serve"}, nil, &buf)
104		if !errors.Is(err, ErrUnknownCommand) {
105			t.Fatalf("WriteHelp(Serve) error = %v, want ErrUnknownCommand", err)
106		}
107		if buf.Len() != 0 {
108			t.Errorf("writer received %d bytes on lookup failure", buf.Len())
109		}
110	}
111	
112	func TestWriteHelpDescriptionVerbatim(t *testing.T) {
113		root := helpTree(t)
114		got := helpString(t, root, nil, nil)
115		if !strings.Contains(got, "\n\nroot tool\n") {
116			t.Errorf("description should follow one blank line verbatim, got %q", got)
117		}
118		multi := New("m", "line one\nline two", nil, noop)
119		got = helpString(t, multi, nil, nil)
120		if got != "Usage: m\n\nline one\nline two\n" {
121			t.Errorf("multi-line description not preserved verbatim: %q", got)
