		if current.handler != nil {
			b.WriteString(" [command]")
		} else {
			b.WriteString(" <command>")
		}
	}
	if parser != nil {
		if len(parser.options) > 0 {
			b.WriteString(" [options]")
		}
		for _, a := range parser.args {
			if a.Variadic {
				fmt.Fprintf(b, " [<%s>...]", a.Name)
