		b.WriteString("  ")
		if opt.Short != "" {
			b.WriteByte('-')
			b.WriteString(opt.Short)
			b.WriteString(", ")
		}
		b.WriteString("--")
		b.WriteString(opt.Long)
		switch opt.Type {
		case TypeString:
			b.WriteString(" <string>")
		case TypeInt:
			b.WriteString(" <int>")
		case TypeDuration:
			b.WriteString(" <duration>")
		}

		var markers []string
		if opt.Required {
			markers = append(markers, "required")
		}
		if opt.Repeatable {
			markers = append(markers, "repeatable")
		}
		if opt.Default != "" {
			markers = append(markers, "default: "+opt.Default)
		}
		if len(markers) > 0 {
			b.WriteString("  (")
			b.WriteString(strings.Join(markers, ", "))
			b.WriteByte(')')
		}
		b.WriteByte('\n')
	}
}

