	want := renderHelp(t, root, []string{"serve"}, p)

	var wg sync.WaitGroup
	for i := 0; i < 24; i++ {
		wg.Add(1)
		go func(aliasPath bool) {
			defer wg.Done()
			for j := 0; j < 30; j++ {
				path := []string{"serve"}
				if aliasPath {
					path = []string{"srv"}
				}
